DESK_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Put Desk Screener</title>\n<style>\n:root{--bg:#0b0f14;--fg:#e5e7eb;--mut:#8b98a5;--card:#0f1419;--line:#1e2a35;--acc:#4ade80;--warn:#f59e0b}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:14px/1.4 system-ui,sans-serif}\nheader{padding:12px 16px;border-bottom:1px solid var(--line)}h1{font-size:18px;margin:0}\n.sub{color:var(--mut);font-size:12px}\n.nav{display:none;gap:14px;margin-top:6px}.nav a{color:var(--mut);text-decoration:none;padding-bottom:3px}.nav a.on{color:var(--fg);border-bottom:2px solid var(--acc)}\n.banner{background:#fde68a;color:#422006;padding:8px 16px;font-weight:600;display:none}\n.wrap{display:grid;grid-template-columns:300px 1fr;gap:12px;padding:12px 16px}\n@media(max-width:820px){.wrap{grid-template-columns:1fr}}\n.panel{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:10px}\n.panel h3{margin:8px 0 4px;font-size:12px;text-transform:uppercase;color:var(--mut);letter-spacing:.04em}\n.f{display:grid;grid-template-columns:1fr 64px 64px;gap:4px;align-items:center;margin:3px 0}\n.f label{font-size:12px}input,select,button{font:inherit;color:var(--fg);background:var(--bg);border:1px solid var(--line);border-radius:4px;padding:3px 5px}\ninput[type=number]{width:100%}button{cursor:pointer}button.p{background:var(--acc);color:#04210f;border-color:var(--acc);font-weight:600}\n.row{display:flex;gap:6px;flex-wrap:wrap;margin:4px 0;align-items:center}\n.tw{overflow:auto;max-height:78vh;border:1px solid var(--line);border-radius:8px;background:var(--card)}\ntable{border-collapse:collapse;width:100%;font-size:12.5px}th,td{padding:4px 7px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}\nth{position:sticky;top:0;background:var(--card);cursor:pointer;user-select:none}th:first-child,td:first-child,th.l,td.l{text-align:left}\ntr:hover td{background:rgba(74,222,128,.07)}.mut{color:var(--mut)}.warn{color:var(--warn)}\nselect[multiple]{width:100%;height:110px}\n</style></head><body>\n<div class="banner" id="banner">SAMPLE DATA: synthetic numbers for testing, not market data.</div>\n<header><h1>Screener v5</h1><div class="nav" id="nav"><a href="/">Ticker scan</a><a class="on" href="/?desk=1">Put screener</a></div><div class="sub" id="metaline">loading…</div>\n<div class="row" id="live" style="display:none;margin-top:8px"><input type="password" id="pw" placeholder="Desk password" autocomplete="current-password" style="width:170px">\n<button class="p" id="goLive">Load live UW data</button><button id="refresh" style="display:none">Refresh from UW</button><span class="mut" id="livemsg"></span></div></header>\n<div class="wrap">\n <div class="panel" id="side">\n  <div class="row"><select id="preset"><option value="">Preset screens…</option></select><button id="reset">Clear</button></div>\n  <div class="mut" id="presetdesc" style="font-size:12px"></div>\n  <h3>Numeric filters (min / max)</h3><div id="nums"></div>\n  <h3>Sector</h3><select id="sectors" multiple></select>\n  <h3>Toggles</h3>\n  <div class="row"><label><input type="checkbox" id="noearn"> No earnings before expiry</label></div>\n  <div class="row"><label><input type="checkbox" id="nolev"> Exclude leveraged / inverse / vol ETPs and index options</label></div>\n  <div class="row"><label><input type="checkbox" id="noexdiv"> No ex-dividend date before expiry</label></div>\n  <h3>Exclude symbols</h3><input id="excl" placeholder="AAPL, TSLA" style="width:100%">\n  <h3>Saved screens</h3>\n  <div class="row"><input id="sname" placeholder="name" style="flex:1"><button id="save">Save</button></div>\n  <div class="row" id="saved"></div>\n  <div class="row"><button id="csv" class="p">Download CSV</button></div>\n  <div class="mut" style="font-size:11px;margin-top:8px">Rank and filters are for triage. Our backtests found put-selling earns equity beta with no measured alpha; read the Stress loss column before anything else.</div>\n </div>\n <div>\n  <div class="row"><b id="count"></b><span class="mut">sort: click a header</span><input type="file" id="file" accept=".json" style="display:none"></div>\n  <div class="tw"><table><thead id="thead"></thead><tbody id="tbody"></tbody></table></div>\n  <div class="row"><button id="more">Show more</button></div>\n </div>\n</div>\n<script>\n"use strict";\nvar NUM=[["dte","DTE",0],["strike","Strike",2],["delta","Delta",2],["annualized_yield","Ann. yield",3],["premium_yield","Prem. yield",3],["credit","Credit",2],\n ["cushion","Cushion",3],["iv","IV",3],["iv_rank","IV rank",0],["pop_delta","POP (delta)",3],["spread_pct","Spread %",3],["open_interest","Open int.",0],["volume","Volume",0],\n ["marketcap","Mkt cap",0],["days_to_earnings","Days to earn.",0],["crash_loss_pct","Stress loss",3],["stress_drop","Stress drop",3],["yield_per_crash_loss","Yield / gap loss",3],["premium_chg_1d","Prem. chg 1D",3],\n ["rsi_14","RSI 14",0],["sma50_dist","vs 50d SMA",3],["sma200_dist","vs 200d SMA",3],["beta","Beta (UW, unreliable)",2],["dividend_yield","Div yield",3],["days_to_ex_div","Days to ex-div",0],\n ["iv30d","IV 30d",3],["realized_vol","Realized vol",3],["vrp","Var. risk prem.",3],["put_call_ratio","Put/call",2],["theta","Theta",3],["vega","Vega",3]];\nvar SHOW=[["ticker","Ticker",0],["sector","Sector",0],["expiry","Expiry",0],["dte","DTE",0],["strike","Strike",2],["delta","Delta",2],["credit","Credit",2],["annualized_yield","Ann. yield",1],\n ["cushion","Cushion",1],["iv","IV",1],["iv_rank","IVR",0],["spread_pct","Spread",1],["open_interest","OI",0],["crash_loss_pct","Stress loss",0],["yield_per_crash_loss","Yld/loss",2],["days_to_earnings","Days to earnings",0]];\nvar PCT={stress_drop:1,sma50_dist:1,sma200_dist:1,dividend_yield:1,iv30d:1,realized_vol:1,vrp:1,annualized_yield:1,cushion:1,iv:1,spread_pct:1,crash_loss_pct:1,premium_yield:1,pop_delta:1,premium_chg_1d:1};\nvar D=null,N=0,screens=[],sortCol=null,sortDesc=true,limit=200,idx=[];\nvar $=function(i){return document.getElementById(i)};\nfunction ls(k,v){try{if(v===undefined)return localStorage.getItem(k);localStorage.setItem(k,v)}catch(e){return null}}\n// ---- the shared grammar, identical to desk/screens.py ----\nfunction passes(i,conds){\n  for(var c=0;c<conds.length;c++){var q=conds[c],col=D.data[q.col],v=col?col[i]:null;\n    if("is" in q){if(!!v!==!!q.is)return false;continue}\n    if(v===null||v===undefined)return false;\n    if("min" in q&&!(v>=q.min))return false;\n    if("max" in q&&!(v<=q.max))return false;\n    if("in" in q&&q.in.indexOf(v)<0)return false;\n    if("not_in" in q&&q.not_in.indexOf(v)>=0)return false;}\n  return true;}\nfunction runConds(conds,rank){\n  var out=[];for(var i=0;i<N;i++)if(passes(i,conds))out.push(i);\n  if(rank&&D.data[rank.by]){var c=D.data[rank.by],s=rank.desc?-1:1;\n    out.sort(function(a,b){var x=c[a],y=c[b];if(x==null)return 1;if(y==null)return -1;return (x-y)*s||a-b});}\n  return out;}\nwindow.__runScreen=function(id){var s=screens.filter(function(x){return x.id===id})[0];return runConds(s.conditions,s.rank).map(function(i){return D.data.option_symbol[i]})};\n// ---- UI state -> conditions ----\nfunction uiConds(){\n  var c=[];NUM.forEach(function(n){var lo=$("min_"+n[0]).value,hi=$("max_"+n[0]).value;\n    if(lo!==""||hi!==""){var q={col:n[0]};if(lo!=="")q.min=+lo;if(hi!=="")q.max=+hi;c.push(q)}});\n  var sel=[].slice.call($("sectors").selectedOptions).map(function(o){return o.value});if(sel.length)c.push({col:"sector",in:sel});\n  if($("noearn").checked){c.push({col:"earnings_in_life",is:false});c.push({col:"earnings_unknown",is:false})}\n  if($("nolev").checked)c.push({col:"leveraged",is:false});\n  if($("noexdiv").checked)c.push({col:"ex_div_in_life",is:false});\n  var ex=$("excl").value.toUpperCase().split(/[\\s,]+/).filter(Boolean);if(ex.length)c.push({col:"ticker",not_in:ex});\n  return c;}\nfunction setUi(conds){\n  NUM.forEach(function(n){$("min_"+n[0]).value="";$("max_"+n[0]).value=""});\n  [].forEach.call($("sectors").options,function(o){o.selected=false});$("noearn").checked=false;$("nolev").checked=false;$("noexdiv").checked=false;$("excl").value="";\n  (conds||[]).forEach(function(q){\n    if(q.col==="earnings_in_life"&&q.is===false)$("noearn").checked=true;\n    else if(q.col==="leveraged"&&q.is===false)$("nolev").checked=true;\n    else if(q.col==="ex_div_in_life"&&q.is===false)$("noexdiv").checked=true;\n    else if(q.col==="sector"&&q.in){[].forEach.call($("sectors").options,function(o){if(q.in.indexOf(o.value)>=0)o.selected=true})}\n    else if(q.col==="ticker"&&q.not_in)$("excl").value=q.not_in.join(", ");\n    else if($("min_"+q.col)){if("min" in q)$("min_"+q.col).value=q.min;if("max" in q)$("max_"+q.col).value=q.max}});}\nfunction fmt(v,d,col){if(v==null)return "-";if(typeof v==="string")return v;if(PCT[col])return (v*100).toFixed(d)+"%";\n  if(col==="marketcap")return (v/1e9).toFixed(1)+"B";return d?v.toFixed(d):Math.round(v).toLocaleString()}\nfunction render(){\n  var conds=uiConds();idx=runConds(conds,sortCol?{by:sortCol,desc:sortDesc}:null);\n  $("count").textContent=idx.length.toLocaleString()+" of "+N.toLocaleString()+" quoted contracts";\n  $("thead").innerHTML="<tr>"+SHOW.map(function(s){return "<th class=\'"+((s[0]==="ticker"||s[0]==="sector"||s[0]==="expiry")?"l":"")+"\' data-c=\'"+s[0]+"\'>"+s[1]+(sortCol===s[0]?(sortDesc?" ▾":" ▴"):"")+"</th>"}).join("")+"</tr>";\n  var rows=idx.slice(0,limit).map(function(i){return "<tr>"+SHOW.map(function(s){var v=D.data[s[0]]?D.data[s[0]][i]:null;\n    var cls=(s[0]==="ticker"||s[0]==="sector"||s[0]==="expiry")?"l":"";if(s[0]==="days_to_earnings"&&v!=null&&v<=D_dte(i))cls+=" warn";\n    return "<td class=\'"+cls+"\'>"+(s[0]==="ticker"?"<b>"+v+"</b>":fmt(v,s[2],s[0]))+"</td>"}).join("")+"</tr>"}).join("");\n  $("tbody").innerHTML=rows;$("more").style.display=idx.length>limit?"":"none";}\nfunction D_dte(i){return D.data.dte?D.data.dte[i]:0}\nfunction csv(){var cols=D.cols,lines=[cols.join(",")];idx.forEach(function(i){lines.push(cols.map(function(c){var v=D.data[c][i];return v==null?"":(typeof v==="string"&&v.indexOf(",")>=0?\'"\'+v+\'"\':v)}).join(","))});\n  var a=document.createElement("a");a.href=URL.createObjectURL(new Blob([lines.join("\\n")],{type:"text/csv"}));a.download="put_screen_"+D.meta.snapshot_date+".csv";a.click();}\nfunction savedList(){var s={};try{s=JSON.parse(ls("saved_screens")||"{}")}catch(e){}return s}\nfunction renderSaved(){var s=savedList(),h="";Object.keys(s).forEach(function(k){h+="<button data-k=\'"+k.replace(/\'/g,"")+"\'>"+k.replace(/</g,"")+"</button>"});$("saved").innerHTML=h}\nfunction init(data){\n  D=data;N=D.n;screens=D.screens;var m=D.meta;\n  $("banner").style.display=m.is_sample?"block":"none";\n  $("metaline").textContent="Snapshot "+m.snapshot_date+" · "+N.toLocaleString()+" quoted puts on "+m.tickers.toLocaleString()+" tickers"+(m.screener_complete===false?" · screener cut off by page cap":"")+" · delta from UW on "+(m.delta_from_uw||0).toLocaleString()+" rows, model on "+(m.delta_from_model||0).toLocaleString();\n  $("nums").innerHTML=NUM.filter(function(n){return D.data[n[0]]}).map(function(n){return "<div class=\'f\'><label>"+n[1]+"</label><input type=\'number\' step=\'any\' id=\'min_"+n[0]+"\' placeholder=\'min\'><input type=\'number\' step=\'any\' id=\'max_"+n[0]+"\' placeholder=\'max\'></div>"}).join("");\n  NUM=NUM.filter(function(n){return D.data[n[0]]});\n  var secs={};(D.data.sector||[]).forEach(function(s){if(s)secs[s]=1});$("sectors").innerHTML=Object.keys(secs).sort().map(function(s){return "<option>"+s+"</option>"}).join("");\n  $("preset").innerHTML="<option value=\'\'>Preset screens…</option>"+screens.map(function(s){return "<option value=\'"+s.id+"\'>"+s.name+"</option>"}).join("");\n  document.body.oninput=function(){limit=200;render()};\n  $("preset").onchange=function(){var s=screens.filter(function(x){return x.id===$("preset").value})[0];$("presetdesc").textContent=s?s.description:"";\n    if(s){setUi(s.conditions);sortCol=s.rank?s.rank.by:null;sortDesc=s.rank?!!s.rank.desc:true}limit=200;render()};\n  $("reset").onclick=function(){setUi([]);$("preset").value="";$("presetdesc").textContent="";sortCol=null;limit=200;render()};\n  $("thead").onclick=function(e){var c=e.target.getAttribute("data-c");if(!c)return;if(sortCol===c)sortDesc=!sortDesc;else{sortCol=c;sortDesc=true}render()};\n  $("more").onclick=function(){limit+=300;render()};$("csv").onclick=csv;\n  $("save").onclick=function(){var n=$("sname").value.trim();if(!n)return;var s=savedList();s[n]=uiConds();ls("saved_screens",JSON.stringify(s));renderSaved()};\n  $("saved").onclick=function(e){var k=e.target.getAttribute("data-k");if(!k)return;var s=savedList()[k];if(s){setUi(s);limit=200;render()}};\n  renderSaved();render();window.__ready=true;}\nfunction pickFile(msg){\n  $("metaline").textContent=msg+" ";var f=$("file");f.style.display="";f.onchange=function(){var r=new FileReader();\n  r.onload=function(){try{init(JSON.parse(r.result))}catch(e){$("metaline").textContent="That file is not a desk data.json ("+e.message+")"}};r.readAsText(f.files[0])};$("metaline").appendChild(f)}\nfunction load(){\n  var inApp=/[?&]desk=/.test(location.search);\n  if(inApp){$("nav").style.display="flex";$("live").style.display="flex";\n    var saved="";try{saved=sessionStorage.getItem("desk_pw")||""}catch(e){}\n    $("pw").value=saved;\n    $("metaline").textContent="Enter the desk password to pull a live Unusual Whales snapshot, or choose a data.json file: ";\n    var f=$("file");f.style.display="";f.onchange=function(){var r=new FileReader();r.onload=function(){try{init(JSON.parse(r.result))}catch(e){$("metaline").textContent="That file is not a desk data.json ("+e.message+")"}};r.readAsText(f.files[0])};$("metaline").appendChild(f);\n    var busy=false;\n    function live(refresh){\n      if(busy)return;busy=true;var t0=Date.now(),pw=$("pw").value;$("livemsg").textContent="Pulling from Unusual Whales (20-40 s)…";\n      var tick=setInterval(function(){$("livemsg").textContent="Pulling from Unusual Whales… "+Math.round((Date.now()-t0)/1000)+" s"},1000);\n      fetch("/?desk_data=1"+(refresh?"&refresh=1":""),{headers:{"X-Desk-Password":pw},cache:"no-store"}).then(function(r){return r.json().then(function(j){return[r.status,j]})}).then(function(x){\n        clearInterval(tick);busy=false;\n        if(x[0]!==200){$("livemsg").textContent=(x[1]&&x[1].error)||("Error "+x[0]);return}\n        try{sessionStorage.setItem("desk_pw",pw)}catch(e){}\n        var c=D?uiConds():null;init(x[1]);if(c){setUi(c);render()}\n        $("refresh").style.display="";$("livemsg").textContent=(x[1].cached?"Cached snapshot (up to 20 min old). ":"Fresh from UW. ")+"Loaded in "+Math.round((Date.now()-t0)/1000)+" s."\n      }).catch(function(){clearInterval(tick);busy=false;$("livemsg").textContent="Could not reach the server (timeout or network). Try again."})}\n    $("goLive").onclick=function(){live(false)};$("refresh").onclick=function(){live(true)};\n    $("pw").onkeydown=function(e){if(e.key==="Enter")live(false)};\n    return}\n  fetch("data.json").then(function(r){if(!r.ok)throw new Error(r.status);return r.json()}).then(init).catch(function(){\n    pickFile("Could not load data.json (opened as a local file, or not published yet). Choose the file:")})}\nload();\n</script></body></html>\n'
